import { fixReasonDefinitions, type FixPatternSummary } from "@clearpath/contracts";

/**
 * One membership relation powers both the chart and the queue filter. It only
 * reads current attention revisions in the already workspace/search/product
 * scoped cohort; it never reconstructs reviewer intent from checks or prose.
 * The definitions parameter is generated by the server, never query input.
 */
export function fixMembershipCtes(definitionsParameter: string): string {
  return `fix_definitions AS (
    SELECT id, source FROM jsonb_to_recordset(${definitionsParameter}::text::jsonb)
      AS definition(id text, source text)
  ), fix_requests AS (
    SELECT DISTINCT ON (e.case_id) e.case_id, e.message, e.change_request
    FROM events e JOIN cases c ON c.id = e.case_id AND c.revision = e.revision
    JOIN cohort a ON a.id = c.id AND a.status = 'changes_requested'
    WHERE e.type = 'changes_requested'
    ORDER BY e.case_id, e.sequence DESC
  ), fix_sources AS MATERIALIZED (
    SELECT a.id, a.status,
      CASE WHEN jsonb_typeof(r.analysis->'checks') = 'array' THEN r.analysis->'checks' ELSE '[]'::jsonb END AS checks,
      e.message, e.change_request,
      CASE WHEN jsonb_typeof(e.change_request->'items') = 'array' THEN e.change_request->'items' ELSE '[]'::jsonb END AS items
    FROM cohort a
    JOIN cases c ON c.id = a.id
    JOIN revisions r ON r.case_id = c.id AND r.number = c.revision
    LEFT JOIN fix_requests e ON e.case_id = a.id
    WHERE a.status IN ('needs_information', 'changes_requested')
  ), fix_candidates AS (
    SELECT s.id, COALESCE(d.id, 'details_unavailable') AS reason
    FROM fix_sources s CROSS JOIN LATERAL jsonb_array_elements(s.checks) item
    LEFT JOIN fix_definitions d ON d.id = 'missing:' || (item->>'ruleId') AND d.source = 'missing_information'
    WHERE s.status = 'needs_information' AND item->>'status' = 'unknown'
    UNION ALL
    SELECT s.id, COALESCE(d.id, 'other_feedback') AS reason
    FROM fix_sources s CROSS JOIN LATERAL jsonb_array_elements(s.items) item
    LEFT JOIN fix_definitions d ON item->>'source' = 'check'
      AND d.id = 'request:' || (item->>'sourceId') AND d.source = 'reviewer_request'
    WHERE s.status = 'changes_requested'
    UNION ALL
    SELECT id, 'other_feedback' AS reason FROM fix_sources
    WHERE status = 'changes_requested' AND (
      (jsonb_typeof(change_request->'note') = 'string' AND (change_request->>'note') ~ '[^[:space:]]')
      OR (COALESCE(jsonb_typeof(change_request), 'null') = 'null' AND COALESCE(message, '') ~ '[^[:space:]]')
    )
    UNION ALL
    -- Keep inconsistent portions accessible even alongside classified sources.
    SELECT id, 'details_unavailable' AS reason FROM fix_sources
    WHERE status = 'changes_requested' AND change_request IS NOT NULL
      AND jsonb_typeof(change_request) <> 'null'
      AND (jsonb_typeof(change_request) <> 'object'
        OR COALESCE(jsonb_typeof(change_request->'items'), 'null') <> 'array'
        OR COALESCE(jsonb_typeof(change_request->'note'), 'null') <> 'string')
  ), fix_memberships AS MATERIALIZED (
    SELECT DISTINCT id, reason FROM fix_candidates
    UNION
    SELECT id, 'details_unavailable' AS reason FROM fix_sources s
    WHERE NOT EXISTS (SELECT 1 FROM fix_candidates candidate WHERE candidate.id = s.id)
  )`;
}

export const fixSummarySql = `jsonb_build_object(
  'total', (SELECT count(DISTINCT id) FROM fix_memberships),
  'counts', COALESCE((SELECT jsonb_object_agg(reason, count) FROM (
    SELECT reason, count(*) AS count FROM fix_memberships GROUP BY reason
  ) grouped), '{}'::jsonb)
)`;

export function readFixPatternSummary(value: { total: number; counts: Record<string, number> } | null): FixPatternSummary | null {
  if (value === null) return null;
  return {
    total: Number(value.total),
    reasons: fixReasonDefinitions.map((definition) => ({ ...definition, count: Number(value.counts[definition.id] ?? 0) }))
      .sort((a, b) => b.count - a.count),
  };
}
